/**
 * Chromatic Resonance: Order and Chaos
 * An animation featuring physical collisions and vivid color transitions.
 */

let particles = []; // Array to store particle data
const numParticles = 300; // Total number of spheres
const baseRadius = 200; // Radius for the "Order" state

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL); // Create 3D canvas
  colorMode(HSB, 360, 100, 100, 100); // Set color mode to Hue, Saturation, Brightness

  for (let i = 0; i < numParticles; i++) {
    // Calculate uniform distribution on a sphere using Fibonacci lattice
    let phi = acos(1 - 2 * (i + 0.5) / numParticles);
    let theta = Math.PI * (1 + 5**0.5) * (i + 0.5);

    particles.push({
      // Original positions for "Order" state
      ox: baseRadius * sin(phi) * cos(theta),
      oy: baseRadius * sin(phi) * sin(theta),
      oz: baseRadius * cos(phi),

      x: 0, y: 0, z: 0, // Current position placeholders
      vx: 0, vy: 0, vz: 0, // Velocity components for repulsion

      targetSize: random(30, 60), // Potential size in chaos state
      myHue: random(0, 360), // Randomized individual color
      noiseSeed: random(1000), // Unique seed for Perlin noise
      speedOffset: random(0.2, 0.6) // Variation in individual movement speed
    });
  }
}

function draw() {
  background(0); // Set background to pitch black
  orbitControl(); // Enable mouse/touch camera control

  // --- Lighting Setup ---
  ambientLight(0, 0, 5); // Very dim ambient light for deep shadows
  directionalLight(0, 0, 100, 1, 1, 0); // Strong white light from the top-right

  // Calculate transition factor (0.0 to 1.0) with half-speed (0.005)
  let cycle = sin(frameCount * 0.005);
  let transition = map(cycle, -1, 1, 0, 1);
  let highE = (window.highEnergy || 0.0);
  let disorderAmt = easeInOutExpo(transition) + highE * 0.5;
  disorderAmt = constrain(disorderAmt, 0, 1); // Apply exponential easing

  rotateY(frameCount * 0.001); // Slow overall scene rotation

  noStroke(); // Disable outlines for a cleaner look

  // 1. Calculate base positions and sizes for each particle
  for (let p of particles) {
    let t = frameCount * 0.005 * p.speedOffset; // Time-based noise input
    let noiseRange = 1500; // Maximum spread distance
    let nx = (noise(p.noiseSeed, t) - 0.5) * noiseRange;
    let ny = (noise(p.noiseSeed + 100, t) - 0.5) * noiseRange;
    let nz = (noise(p.noiseSeed + 200, t) - 0.5) * noiseRange;

    // Interpolate between ordered and noisy positions
    p.x = lerp(p.ox, nx, disorderAmt);
    p.y = lerp(p.oy, ny, disorderAmt);
    p.z = lerp(p.oz, nz, disorderAmt);
    p.size = lerp(6, p.targetSize, disorderAmt); // Interpolate size
  }

  // 2. Collision Detection and Resolution (Hard surface logic)
  if (disorderAmt > 0.05) {
    for (let iter = 0; iter < 2; iter++) { // Perform twice for stability
      for (let i = 0; i < particles.length; i++) {
        for (let j = i + 1; j < particles.length; j++) {
          let p1 = particles[i];
          let p2 = particles[j];

          // Vector between two spheres
          let dx = (p2.x + p2.vx) - (p1.x + p1.vx);
          let dy = (p2.y + p2.vy) - (p1.y + p1.vy);
          let dz = (p2.z + p2.vz) - (p1.z + p1.vz);

          let d2 = dx*dx + dy*dy + dz*dz; // Square distance for performance
          let minD = p1.size + p2.size; // Sum of radii (collision boundary)

          if (d2 < minD * minD && d2 > 0) {
            let d = sqrt(d2); // Actual distance
            let overlap = (minD - d); // How much spheres are intersecting

            let nx = dx / d; // Normalized direction X
            let ny = dy / d; // Normalized direction Y
            let nz = dz / d; // Normalized direction Z

            let moveAmt = overlap * 0.5; // Distribute repulsion equally
            p1.vx -= nx * moveAmt; // Push sphere 1 away
            p1.vy -= ny * moveAmt;
            p1.vz -= nz * moveAmt;
            p2.vx += nx * moveAmt; // Push sphere 2 away
            p2.vy += ny * moveAmt;
            p2.vz += nz * moveAmt;
          }
        }
      }
    }
  }

  // Apply friction to dampen velocities
  for (let p of particles) {
    p.vx *= 0.7;
    p.vy *= 0.7;
    p.vz *= 0.7;
  }

  // 3. Render spheres
  for (let p of particles) {
    push(); // Save current transformation state

    translate(p.x + p.vx, p.y + p.vy, p.z + p.vz); // Move to calculated position

    // Calculate dynamic color (transition from Blue to Individual Rainbow)
    let highE = (window.highEnergy || 0.0);
    let h = (lerp(280, 340, disorderAmt) + highE * 60) % 360;
    let s = 100; // Full saturation
    let b = map(disorderAmt, 0, 1, 60, 100); // Brighten as they expand

    // Calculate visual flash intensity based on collision force
    let repulsionMag = sqrt(p.vx*p.vx + p.vy*p.vy + p.vz*p.vz);
    let flash = map(repulsionMag, 0, 10, 0, 50);

    // Set material properties
    emissiveMaterial(h, s, map(disorderAmt, 0, 1, 5, 20) + flash); // Glow effect
    specularMaterial(h, s, b); // Shiny surface
    shininess(100); // Maximum glossiness

    sphere(p.size, 10, 10); // Draw the sphere with low-poly detail for performance

    pop(); // Restore transformation state
  }
}

// Exponential easing function for dramatic transitions
function easeInOutExpo(x) {
  return x === 0 ? 0 : x === 1 ? 1 : x < 0.5 
    ? pow(2, 20 * x - 10) / 2 
    : (2 - pow(2, -20 * x + 10)) / 2;
}

// Adjust canvas size when window is resized
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

// --- Immunity Guardrails ---
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

